import React from 'react';
import { RecipeCard } from '../../components/page/recipes/RecipeCard';

export const RecipesPage = (recipes) => {
  return (
    <div className='grid grid-cols-3 gap-4'>
      {recipes.map((recipe) => (
        <RecipeCard recipe={recipe}/>
      ))}
    </div>
  )
}
